const rows = $input.all().map(i => i.json);
const DIRECT_ACCESS_CUSTOMER_IDS = ['3534195221'];
const out = [];
for (const row of rows) {
  if (!row.google_ads_customer_id || !row.google_ads_campaign_resource) continue;
  const customerId = String(row.google_ads_customer_id).replace(/[^0-9]/g, '');
  const googleCampaignId = row.google_ads_campaign_resource.split('/campaigns/')[1];
  if (!googleCampaignId) continue;
  out.push({
    json: {
      campaignRowId: row.id,
      customerId,
      googleCampaignId,
      loginCustomerId: DIRECT_ACCESS_CUSTOMER_IDS.includes(customerId) ? '' : $('Get Google Ads credentials').first().json.mcc_customer_id,
      campaignName: row.campaign_name,
      status: row.status,
      dailyBudgetUsd: row.daily_budget_usd,
    },
  });
}
return out;

