const campaigns = $('Filter buildable campaigns').all();
const searches = $('Search campaign metrics').all();
const fallbackDate = new Date(Date.now() - 86400000).toISOString().slice(0, 10);

return campaigns.map((c, i) => {
  const results = (searches[i] && searches[i].json.results) || [];
  const row = results[0];
  return {
    json: {
      campaignRowId: c.json.campaignRowId,
      campaign_id: c.json.campaignRowId,
      date: row ? row.segments.date : fallbackDate,
      cost: row ? Number(row.metrics.costMicros || 0) / 1000000 : 0,
      conversions: row ? Number(row.metrics.conversions || 0) : 0,
      conversions_value: row ? Number(row.metrics.conversionsValue || 0) : 0,
      impressions: row ? Number(row.metrics.impressions || 0) : 0,
      clicks: row ? Number(row.metrics.clicks || 0) : 0,
    },
  };
});

const campaigns = $('Filter buildable campaigns').all();
const metricsRows = $('Build metrics row').all();
const allRecs = $('Get fresh recommendations').all().map(i => i.json).filter(r => r && r.id);

return campaigns.map((c, i) => {
  const campaign = c.json;
  const metricsRow = (metricsRows[i] && metricsRows[i].json) || {};
  const recRows = allRecs.filter(r => r.campaign_id === campaign.campaignRowId);
  const roas = metricsRow.cost > 0 ? metricsRow.conversions_value / metricsRow.cost : null;
  const recsText = recRows.length
    ? recRows.map(r => '- ' + r.type + ': $' + r.dollars_recoverable + ' recoverable').join('\n')
    : 'None currently open.';

  return {
    json: {
      campaignRowId: campaign.campaignRowId,
      campaignName: campaign.campaignName,
      status: campaign.status,
      dailyBudgetUsd: campaign.dailyBudgetUsd,
      date: metricsRow.date,
      cost: metricsRow.cost,
      conversions: metricsRow.conversions,
      conversionsValue: metricsRow.conversions_value,
      roas,
      recommendationsText: recsText,
    },
  };
});

const aiOutputs = $input.all();
const contexts = $('Build suggestion context').all();

return aiOutputs.map((item, i) => {
  const output = item.json.output;
  const campaignRowId = (contexts[i] && contexts[i].json.campaignRowId) || null;
  return {
    json: {
      campaignRowId,
      shouldPost: !!output.should_post,
      message: output.message,
      proposedAction: output.proposed_action || null,
      actionStatus: output.proposed_action ? 'proposed' : null,
    },
  };
});

