const campaigns = $('Filter buildable campaigns').all();
const searches = $('Search recommendations').all();
const output = [];

campaigns.forEach((c, i) => {
  const campaignRowId = c.json.campaignRowId;
  const results = (searches[i] && searches[i].json.results) || [];
  for (const r of results) {
    const rec = r.recommendation;
    const base = rec.impact.baseMetrics;
    const potential = rec.impact.potentialMetrics;
    const baseCost = Number(base.costMicros || 0) / 1000000;
    const potentialCost = Number(potential.costMicros || 0) / 1000000;
    const valueGain = Number(potential.conversionsValue || 0) - Number(base.conversionsValue || 0);
    const costSavings = baseCost - potentialCost;
    const dollarsRecoverable = valueGain > 0 ? valueGain : Math.max(costSavings, 0);
    output.push({
      json: {
        campaign_id: campaignRowId,
        type: rec.type,
        dollars_recoverable: dollarsRecoverable,
        resource_name: rec.resourceName,
        status: 'open',
      },
    });
  }
});

return output;

